void swap(shared_lock<Mutex> &lhs,

    shared_lock<Mutex> &rhs) noexcept;

examples.code:
#include <mutex>
#include <shared_mutex>
#include <chrono>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::timed_mutex mutex;
    {
        std::lock_guard<std::timed_mutex> guard{mutex};
    }
    {
        std::scoped_lock guard{mutex};
    }
    std::unique_lock<std::timed_mutex> owner{mutex, std::defer_lock};
    assert(owner.mutex() == &mutex && !owner.owns_lock());
    assert(
        owner.try_lock_for(std::chrono::milliseconds(10)) && static_cast<bool>(owner));
    owner.unlock();
    assert(owner.try_lock_until(
        std::chrono::steady_clock::now() + std::chrono::seconds(1)));
    owner.unlock();
    std::unique_lock<std::timed_mutex> other;
    other = std::move(owner);
    std::swap(owner, other);
    auto *raw = owner.release();
    assert(raw == &mutex);
    std::shared_timed_mutex shared;
    std::shared_lock<std::shared_timed_mutex> reader{shared, std::defer_lock};
    assert(reader.mutex() == &shared && !reader.owns_lock());
    assert(reader.try_lock() && static_cast<bool>(reader));
    reader.unlock();
    assert(reader.try_lock_for(std::chrono::milliseconds(10)));
    reader.unlock();
    assert(reader.try_lock_until(
        std::chrono::steady_clock::now() + std::chrono::seconds(1)));
    reader.unlock();
    std::shared_lock<std::shared_timed_mutex> copy;
    copy = std::move(reader);
    copy.swap(reader);
    std::swap(copy, reader);
    assert(copy.release() == &shared);
}
